{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Abnormal seat server spans: 7 calls, all Error 403, p95 about 131 s; normal p95 about 11 ms."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='SeatController.getLeftTicketOfInterval' GROUP BY ALL", "claim": "SeatController.getLeftTicketOfInterval self-time reaches about 130 s in the abnormal window, with no child client calls."},
        {"kind": "trace", "sql": "SELECT c.service_name AS caller, c.attr_status_code, c.attr_http_response_status_code, round(c.duration/1e6,1) caller_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id WHERE s.service_name='ts-seat-service' AND s.attr_span_kind='Server' AND c.attr_span_kind='Client'", "claim": "Travel and travel2 client calls into seat return 403 after about 130 s, matching seat's stalled handler."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel2-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, s.span_name, count(*) n, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errs, round(approx_quantile(s.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND s.service_name IN ('ts-seat-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service') GROUP BY ALL ORDER BY n DESC", "claim": "travel2 calls to seat fail with 403 after about 130 s, so travel2 requests inherit the stall."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, s.span_name, count(*) n, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errs, round(approx_quantile(s.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND s.service_name IN ('ts-seat-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service') GROUP BY ALL ORDER BY n DESC", "claim": "route-plan calls to travel2 show callee p95 around 39 s and errors in abnormal window."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, s.span_name, count(*) n, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errs, round(approx_quantile(s.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND s.service_name IN ('ts-seat-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service') GROUP BY ALL ORDER BY n DESC", "claim": "travel-plan calls to route-plan show callee p95 above 100 s with errors in abnormal window."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, attr_span_kind, attr_status_code, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' GROUP BY ALL", "claim": "Travel-plan server spans for quickest/cheapest/minStop requests error with 403 after about 130 s; ui-dashboard sees the same delay."}]}
  ]
}
